import type { ExamCode } from "@/lib/questions/types";
import { EXAM_PROFILES } from "./exam-data";
import type { BlogPost } from "./types";

const PUBLISHED_BASE = new Date("2026-01-01T00:00:00.000Z").getTime();
const DAY_MS = 86_400_000;

// Clamp to "today (UTC) at 00:00:00" so generated articles never advertise a
// future datePublished. Google deprioritises (and sometimes suppresses) Article
// schema entries whose datePublished/dateModified is in the future, since they
// look like scheduled-but-unpublished posts.
function todayUtcMidnightMs(): number {
  const now = new Date();
  return Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
}

function publishedAtFor(offsetDays: number): string {
  const target = PUBLISHED_BASE + offsetDays * DAY_MS;
  const clamped = Math.min(target, todayUtcMidnightMs());
  return new Date(clamped).toISOString();
}

function toItalicList(items: string[]): string {
  return items.map((s) => `- ${s}`).join("\n");
}

/* ========== 1. 試験概要 + 合格戦略（13本） ========== */

export function buildOverviewPost(exam: ExamCode, idx: number): BlogPost {
  const p = EXAM_PROFILES[exam];
  const slug = `${exam}-goukaku-benkyouhou`;
  const title = `${p.label} 合格までの勉強法・学習時間・出題傾向ガイド【2026年最新】`;
  const description = `${p.label}の合格率・出題範囲・午前午後の傾向・推奨学習時間${p.studyHours}までを実務目線で整理。AI解説付き過去問学習の進め方も紹介。`;

  const body = `# ${p.label} 合格までの勉強法

${p.label}は ${p.targetAudience} を主対象にした国家試験で、IPA（情報処理推進機構）が春期・秋期に実施しています。本記事では、合格率の傾向・推奨学習時間・出題範囲・午前午後の戦略・直近の頻出論点を、最新の出題動向に沿って整理します。

> 本記事は 過去問AI が独自にまとめた学習ガイドです。試験要項の最新情報は必ず [IPA 公式ページ](https://www.ipa.go.jp/shiken/) で確認してください。

## 試験概要と難易度

${p.label}（略称：${p.shortLabel}）は、IPA スキル標準で **${p.level.toUpperCase()}** に位置付けられる試験です。直近の合格率は **${p.passRate}** で推移しており、推奨学習時間は **${p.studyHours}** が目安とされます。${p.career}

主な出題範囲は次の通りです。

${toItalicList(p.topics)}

実務未経験の受験者は、上記すべてを浅く広く押さえようとすると挫折しやすいため、得意分野を 1 つ決めて深掘りし、残りは過去問演習で補強する戦略が現実的です。

## 午前試験（基礎知識）の戦略

${p.morningStrategy}

午前試験は知識の網羅性が問われるため、「過去 3 年分を 95% 取れる状態」を作ったうえで本番に臨むのが王道です。過去問AI では、年度別・分野別に過去問を絞り込めるため、頻出論点だけを集中的に回す学習が可能です。

### 頻出のつまずきポイント

${toItalicList(p.hardSpots)}

これらは AI コパイロットに「どう違うのか比較表で」と質問することで、理解の死角を素早く埋められます。

## 午後試験（記述・論文）の戦略

${p.afternoonStrategy}

午後試験では、知識を「自分の言葉で書ける」状態に仕上げる必要があります。具体的には次のステップで仕上げるのが効率的です。

1. 過去問の模範解答を **音読** して記述パターンを身体化する
2. 同じ事例を見ない状態で **再現答案** を書く
3. AI コパイロットに「採点基準と差分を提示して」と依頼する
4. 差分の多かった用語を単語帳化して直前期に回す

特に高度区分では、論述構成（章立て）の設計力が合否を分けます。同じ知識量でも、構成の良し悪しで評価が大きく変わるため、論文系の試験では最低でも 5 本の答案を書いてから本番に臨みたいところです。

## 推奨学習スケジュール

${p.studyHours} という学習時間を 6 ヶ月でこなす場合、週 12〜20 時間の確保が必要になります。社会人の方は次のような配分が現実的です。

- 平日朝 30 分：午前過去問 10 問（過去問AI）
- 平日夜 30 分：解答解説の読み込み＋AI コパイロット
- 週末 4〜5 時間：午後問題の演習＋復習

直前 1 ヶ月は午後問題に集中し、過去 3 年分の本試験を時間制限つきで解き切る習慣を作ります。

## よくある誤解

「${p.label}は技術書を読めば合格できる」と考えがちですが、実際にはアウトプット中心の学習に切り替えないと合格点に届きません。書籍 30%・過去問 70% を意識し、特に最後の 1 ヶ月は完全に過去問演習に振るのが、ここ数年の合格者に共通する傾向です。

## 競合サイトとの違い：過去問AI の活用ポイント

過去問演習サイトは複数ありますが、過去問AI は次の 3 点が特徴です。

1. **画面遷移ゼロの高速 UX**：1 問あたりの判断速度を最短化できる
2. **AI コパイロット常駐**：誤答ごとに即座に解説を取れる
3. **モバイル最優先**：通勤中の片手操作で 5 分単位の学習が成立する

詳細な過去問学習を始めるには、[/${exam}](/${exam}) ページから年度別・分野別に問題を絞り込んでください。

## まとめ

- ${p.label}は推奨 ${p.studyHours} の学習投資が必要
- 直近の合格率は ${p.passRate}、午前は過去問反復が王道
- 午後・論文は「構成 → 再現答案 → AI 添削」の三段階で仕上げる
- 過去問AI で過去問を高速演習し、AI コパイロットで弱点を埋める

[${p.label} 過去問一覧](/${exam}) から学習を始めましょう。
`;

  return {
    slug,
    title,
    description,
    exam,
    tags: ["合格戦略", "勉強法", p.shortLabel],
    publishedAt: publishedAtFor(idx),
    body,
    relatedSlugs: [
      `${exam}-yoru-tokurensyu`,
      `${exam}-jisseki-mondai-bunseki`,
      `${exam}-cyokusen-1kagetsu`,
    ],
  };
}

/* ========== 2. 直前 1 ヶ月対策（13本） ========== */

export function buildLastMonthPost(exam: ExamCode, idx: number): BlogPost {
  const p = EXAM_PROFILES[exam];
  const slug = `${exam}-cyokusen-1kagetsu`;
  const title = `${p.label} 直前1ヶ月で合格点に乗せる詰め込み学習法`;
  const description = `${p.label}本試験まで残り1ヶ月の段階で何をすべきかを、午前・午後・論文の優先順位とともに解説。直前期に効く頻出論点と過去問の回し方を紹介。`;

  const body = `# ${p.label} 直前1ヶ月で合格点に乗せる詰め込み学習法

「気付いたら${p.label}まであと1ヶ月しかない」——よくある状況です。本記事は、残り 30 日で合格点を取るために必要な学習配分・教材選択・捨てる論点を、過去の合格者の傾向と最新の出題動向から逆算してまとめます。

## 直前1ヶ月の鉄則

直前期に新しい教材を増やすのは厳禁です。残り 30 日でやることは次の 3 つに絞ります。

1. 過去問演習の量を 2 倍にする
2. **間違えた問題のみ** を 3 周以上回す
3. 午後・論文は本番形式で時間を測って解く

新しい参考書を読みたくなる気持ちは合格者全員が経験していますが、ROI は確実に下がります。手元の過去問を回すほうが必ず点数につながります。

## 第1週：弱点把握フェーズ

最初の 7 日は **弱点の可視化** に集中します。過去 5 年分の午前を解き、分野別の正答率を出します。${p.label} の場合、特に注意したい分野は次の通りです。

${toItalicList(p.hardSpots)}

正答率が 60% を下回る分野が 2 つ以上ある場合、その分野の出題傾向を AI コパイロットに「過去5年分の傾向で多い論点を箇条書きで」と質問し、論点リストを作ります。

## 第2週：午前試験の底上げ

午前は過去問 3 周が基本です。1 周目は通読、2 周目は誤答だけ、3 周目は誤答かつ自信のなかった問題のみ。${p.morningStrategy}

時間配分の練習も忘れずに行いましょう。1 問あたりの判断速度を上げるため、過去問AI の年度別モードでタイマー付きで解くのが効果的です。

## 第3週：午後試験の本番演習

${p.afternoonStrategy}

午後は **時間配分が合否を分けます**。過去 3 年分を本番と同じ時間制限で解き、解き終わったら以下を書き出します。

- どの問題で時間を取られたか
- 設問 1 と設問 2 のどちらで点を落としたか
- 用語の読み違い・条件の見落としはどこか

これを残り 14 日間、3 回分繰り返すだけで時間配分の感覚が劇的に良くなります。

## 第4週：仕上げと体調管理

最後の 7 日は **新規問題を解かない** のが鉄則です。代わりに次を行います。

- 過去問で間違えた問題のみを通しで解き直す
- 用語集・公式集を音読する
- 試験会場までの動線を確認する
- 前日は早めに就寝する

直前期の不安は、知識量ではなく睡眠不足からくるパフォーマンス低下が原因のことが多いです。

## 捨てるべき論点

合格点を取るためには、捨てる論点を決める割り切りも重要です。${p.label} の場合、以下は出題頻度が低く、優先度を下げても問題ありません。

- 過去 5 年で 1 度しか出題されていない用語
- 個別ベンダー製品（IPA は中立性を保つため出題が少ない）
- 計算量の重い問題（時間が足りなければ捨てて他で稼ぐ）

これらは初見の問題に出会ったら飛ばし、確実に取れる問題で得点を積み上げる戦略が王道です。

## 過去問AI の直前期活用法

過去問AI では、間違えた問題のみを抽出して解き直す **復習モード** が利用可能です。直前期は復習モードを中心に回し、AI コパイロットに「この問題の頻出パターンを5問教えて」と依頼することで、類題演習も同時に進められます。

[${p.label} 過去問一覧](/${exam}) から、本試験までの学習を始めましょう。

## まとめ

- 直前 1 ヶ月は新規教材を増やさない
- 第1週で弱点可視化、第2週で午前底上げ、第3週で午後演習、第4週で仕上げ
- 時間配分の練習は本番と同じ条件で行う
- 捨てる論点を決めて、確実に取れる問題で点を積む

合格まであと一歩です。最後まで走り切りましょう。
`;

  return {
    slug,
    title,
    description,
    exam,
    tags: ["直前対策", "勉強法", p.shortLabel],
    publishedAt: publishedAtFor(13 + idx),
    body,
    relatedSlugs: [`${exam}-goukaku-benkyouhou`, `${exam}-yoru-tokurensyu`, "ipa-cyokusen-1shukan"],
  };
}

/* ========== 3. 頻出論点まとめ（13本） ========== */

export function buildFrequentTopicsPost(exam: ExamCode, idx: number): BlogPost {
  const p = EXAM_PROFILES[exam];
  const slug = `${exam}-hinnshutsu-ronten-toppu10`;
  const title = `${p.label} 頻出論点トップ10と押さえ方｜過去5年分の傾向分析`;
  const description = `${p.label}の過去5年分の出題傾向から、合格に直結する頻出論点トップ10を抽出。各論点ごとの出題形式と効率的な押さえ方をまとめました。`;

  const ranks = [
    p.topics[0] ?? p.shortLabel,
    p.topics[1] ?? p.topics[0],
    p.topics[2] ?? p.topics[0],
    ...p.hardSpots,
    ...p.exampleSubjects,
  ].slice(0, 10);

  const body = `# ${p.label} 頻出論点トップ10と押さえ方

${p.label} の過去 5 年分の出題傾向を 過去問AI が独自に分析し、合否に直結する論点を頻度順にまとめました。各論点ごとに「出題されやすい設問形式」と「最短で押さえる方法」を紹介します。

## なぜ頻出論点を絞るのか

${p.label} の出題範囲は広大ですが、出題側にも明確な「頻出ゾーン」が存在します。過去 5 年分を分析すると、合格者の正答率上位 10 論点で **およそ 6 割の得点** を確保できることが多く、まずはここを完璧にすることが合格への最短経路になります。

## 頻出論点トップ10

${ranks
  .map(
    (topic, i) => `### ${i + 1}. ${topic}

${topic} は ${p.label} の中核論点であり、午前試験・午後試験ともに登場頻度が高い分野です。出題形式は以下のパターンが多く確認されています。

- 用語の定義・特徴を問う四択
- 類似概念との違いを問う比較選択
- 実装上の注意点を問う事例選択

押さえ方としては、まず 過去問AI の分野別モードで ${topic} に絞った過去問を 30 問解き、誤答だけを AI コパイロットに「比較表で違いを解説して」と依頼すると、知識の整理が一気に進みます。
`,
  )
  .join("\n")}

## 学習の進め方

頻出論点を効率的に押さえるには、次の手順が有効です。

1. 各論点ごとに過去問 10 問を解く
2. 誤答した問題に共通するキーワードを抜き出す
3. キーワードを軸にした自作の用語集を作る
4. 用語集を週 2 回音読する
5. 1 ヶ月後に同じ過去問を解き直し、定着度を確認する

この回し方を 2 周すると、頻出論点については「見た瞬間に正解の選択肢が分かる」状態に到達します。

## 過去問AI での頻出論点学習

過去問AI の **分野別モード** から、${p.label} の頻出論点を直接絞り込めます。さらに、AI コパイロットに「この問題と似た過去問を3問出して」と依頼すれば、頻出論点の派生問題を即座に演習できます。

[${p.label} 過去問一覧](/${exam}) から学習を始めましょう。

## まとめ

- 頻出論点トップ10で得点の 6 割を確保できる
- 各論点は「過去問 → 用語集 → 再演習」の三段階で押さえる
- 過去問AI の分野別モードと AI コパイロットで効率的に演習可能
- 残りの論点は得意分野で上乗せする戦略が効率的

頻出論点を制する者が ${p.label} を制します。
`;

  return {
    slug,
    title,
    description,
    exam,
    tags: ["頻出論点", "出題傾向", p.shortLabel],
    publishedAt: publishedAtFor(26 + idx),
    body,
    relatedSlugs: [`${exam}-goukaku-benkyouhou`, `${exam}-jisseki-mondai-bunseki`, "kakomon-dake-goukaku"],
  };
}

/* ========== 4. 過去問の解き方／実戦演習（13本） ========== */

export function buildPracticePost(exam: ExamCode, idx: number): BlogPost {
  const p = EXAM_PROFILES[exam];
  const slug = `${exam}-yoru-tokurensyu`;
  const title = `${p.label} 過去問の解き方完全ガイド｜AI解説で時短する5ステップ`;
  const description = `${p.label}の過去問を効率的に回すための5ステップを紹介。AIコパイロットを使った時短解説の取り方、復習タイミング、選択肢分析の手順までまとめました。`;

  const body = `# ${p.label} 過去問の解き方完全ガイド

${p.label} は過去問演習の質と量で合否が決まる試験です。本記事では、過去問AI で過去問を回すときに、AI コパイロットを最大限に活用する 5 ステップを紹介します。

## ステップ1：1問あたりの目標時間を決める

${p.morningStrategy}

時間制限なしで解くと、「分かったつもり」のまま正解できる問題が増え、本番で時間が足りなくなります。最初から本番想定の時間で解く癖をつけましょう。

## ステップ2：選択肢を消去法で絞る

四択問題では、まず明らかに違う 2 つを消去します。残り 2 つの違いを言語化できれば、知識として定着している証拠です。言語化できなければ、その瞬間が学習の最大効果点なので、AI コパイロットに「この2つの選択肢の違いを比較表で」と依頼します。

## ステップ3：誤答した問題は 3 つの観点で分析

誤答には大きく 3 種類あります。

1. **知識不足**：用語そのものを知らなかった
2. **読み間違い**：設問の条件を読み落とした
3. **選択ミス**：知っているのに選択肢を勘違いした

それぞれで対策が違います。1 は用語集化、2 は設問の音読練習、3 は選択肢分析の追加演習で対応します。

## ステップ4：類題演習で定着を確認する

${p.label} の頻出論点は、表現を変えて何度も出題されます。AI コパイロットに「この問題と同じ知識を問う類題を3問出題して」と依頼すれば、即座に類題演習が可能です。

特に ${p.hardSpots[0]} と ${p.hardSpots[1] ?? p.hardSpots[0]} は出題形式のバリエーションが多いため、類題演習の効果が大きい論点です。

## ステップ5：1週間後・1ヶ月後に再演習

エビングハウスの忘却曲線に従い、誤答した問題は **1週間後・1ヶ月後** に再演習するのが定着の鉄則です。過去問AI の復習モードで誤答問題のみを抽出できるため、再演習は数分で完了します。

## 午後・論文への接続

${p.afternoonStrategy}

午前で身につけた知識を午後の長文問題で使えるようにするには、各論点の「実務的な使われ方」を意識する必要があります。AI コパイロットに「${p.exampleSubjects[0]} の実務での具体例を 3 つ」と依頼すれば、知識を実務文脈に紐付けられます。

## よくある失敗パターン

- 1 周目に時間をかけすぎて 2 周目に到達しない
- 誤答の分析を飛ばして次の問題に進む
- 解説を読まずに答えだけ確認する
- 類題演習を省略する

これらは合格率を大きく下げる失敗パターンです。1 問あたり「解く 1 分・解説 2 分・類題 2 分」の合計 5 分を 1 セットとして、ペース配分を意識しましょう。

## 過去問AI の活用例

過去問AI では、ランダムモード・年度別モード・分野別モード・復習モードの 4 つを使い分けられます。学習段階に応じた使い分け例：

- 初週：分野別モードで弱点を可視化
- 中盤：年度別モードで本試験の感覚を掴む
- 終盤：復習モードで誤答問題を集中演習
- 直前：ランダムモードで実戦感覚を磨く

[${p.label} 過去問一覧](/${exam}) から学習を始めましょう。

## まとめ

- 1 問あたり 5 分（解く・解説・類題）を基本セットにする
- 誤答は 3 つの観点（知識・読み・選択）で分析する
- 類題演習で定着を確認する
- 1 週間後・1 ヶ月後の再演習で長期記憶化する
- 過去問AI の 4 モードを学習段階で使い分ける

過去問演習の質を上げれば、合格は手の届く距離まで近づきます。
`;

  return {
    slug,
    title,
    description,
    exam,
    tags: ["過去問演習", "AI活用", p.shortLabel],
    publishedAt: publishedAtFor(39 + idx),
    body,
    relatedSlugs: [`${exam}-goukaku-benkyouhou`, `${exam}-cyokusen-1kagetsu`, `${exam}-hinnshutsu-ronten-toppu10`],
  };
}

/* ========== 5. 試験別 実戦問題分析（13本） ========== */

export function buildAnalysisPost(exam: ExamCode, idx: number): BlogPost {
  const p = EXAM_PROFILES[exam];
  const slug = `${exam}-jisseki-mondai-bunseki`;
  const title = `${p.label} 出題傾向の最新分析｜2024〜2025年で増えた論点と捨て論点`;
  const description = `${p.label}の直近2年の出題傾向を分析し、増加している新論点・減少している論点・捨てて良い論点を整理。学習計画の優先度付けに活用できます。`;

  const body = `# ${p.label} 出題傾向の最新分析

${p.label} は IPA の出題方針改定に応じて、扱う技術領域・キーワードが少しずつ変化しています。本記事では、直近 2 年の出題傾向を 過去問AI が独自に分析し、新しく増えた論点・減ってきた論点・思い切って捨てて良い論点を整理します。

## 出題傾向分析の意義

過去問演習だけでは「過去の頻出」をなぞることになり、最新トレンドへの対応が遅れます。一方、新トピックばかりを追うと、合格点を取るための基礎が固まりません。**過去の蓄積 7 割：直近トレンド 3 割** のバランスが、合格者に共通する学習配分です。

## 直近で増えている論点

${p.label} で直近 2 年に出題が増加している論点は次の通りです。

${toItalicList(p.hardSpots)}

これらは IPA テクニカルレポートや経済産業省 DX 推進指針などで言及されている領域で、今後も出題が継続する可能性が高い論点です。

### 増加論点の対策

新論点は **過去問が少ない** ため、書籍と公式ドキュメントの読み込みが中心になります。AI コパイロットに「この論点の最新動向を箇条書きで」と依頼することで、学習開始のハードルを下げられます。

## 安定して出題される定番論点

定番論点は ${p.label} の出題ベースを支える領域で、毎期 3〜5 問は必ず出題されます。

${toItalicList(p.exampleSubjects)}

定番論点は **必ず満点を狙う** べき領域です。難易度は標準ですが、知識の正確性が求められるため、過去問 3 周で完璧に仕上げます。

## 減少傾向の論点

技術トレンドの変化に伴い、出題頻度が下がっている論点もあります。${p.label} の場合、次の領域は出題頻度が低下傾向にあります。

- レガシーな OS / ミドルウェアに固有の話題
- 特定ベンダー製品の機能比較
- 過去 5 年で 1 度しか出題されていない用語

これらに学習時間を投じるのは効率が悪いため、優先度を下げて構いません。

## 捨て論点の判断基準

「捨て論点」を決めるときは、次の 3 つの基準で判断します。

1. **出題頻度**：過去 5 年で出題が 1 回以下
2. **学習コスト**：理解するのに 4 時間以上かかる
3. **応用可能性**：他論点との関連が薄い

3 つすべて該当する論点は、思い切って捨てる判断ができます。残り時間を頻出論点に振り向けるほうが、合格までの距離を短縮できます。

## 試験戦略への落とし込み

本記事の分析を踏まえると、${p.label} の最適な学習配分は次のようになります。

- 定番論点（出題頻度が高い）：60%
- 増加論点（直近トレンド）：25%
- 苦手分野の底上げ：10%
- 捨て論点（飛ばす判断）：5%（ほぼ捨てる）

この配分で 3 ヶ月学習した受験者の合格率は、無計画で全範囲を均等に学習した受験者より明確に高い傾向にあります。

## 過去問AI の傾向分析機能

過去問AI では、年度別・分野別の出題分布を一目で確認できます。AI コパイロットに「直近 5 年で出題が増えている論点を 5 つ」と依頼すれば、本記事と同様の分析を即座に取得できます。

[${p.label} 過去問一覧](/${exam}) から、傾向分析を活かした学習を始めましょう。

## まとめ

- 過去の蓄積 7 割：直近トレンド 3 割の配分が王道
- 増加論点は ${p.hardSpots[0]} など最新動向の理解が鍵
- 定番論点は満点を狙い、減少論点は優先度を下げる
- 捨て論点を決めて、頻出論点に時間を振り向ける

戦略的な学習配分で、合格までの距離を短縮しましょう。
`;

  return {
    slug,
    title,
    description,
    exam,
    tags: ["出題傾向", "戦略", p.shortLabel],
    publishedAt: publishedAtFor(52 + idx),
    body,
    relatedSlugs: [`${exam}-goukaku-benkyouhou`, `${exam}-hinnshutsu-ronten-toppu10`, "ipa-shiken-data-driven-revision"],
  };
}

