    body: `# 情報処理安全確保支援士｜午後事例を「物語」で読む

SC 午後事例は、サイバーインシデントを 1 本の物語として読むのが得点最短コースです。技術用語を覚える前に、「いつ・どこから・誰が・どう動いたか」を時系列に再構成しましょう。

## 物語の典型構造

1. **発覚**：アラート / 利用者通報 / 監査での気付き
2. **侵入経路の推定**：フィッシング / 公開資産の脆弱性 / 内部不正
3. **封じ込め**：隔離 / 通信遮断 / 認証情報リセット
4. **復旧と恒久対策**：パッチ / 監視強化 / 社内教育

## 設問は構造に紐付く

各設問は構造のどこを問うているかを最初に判定するのが肝。事例を全部読んでから設問を見るのではなく、設問 → 構造マッピング → 事例から該当箇所抽出 の順で時間を節約します。

## 過去問 AI 活用法

[SC 過去問](/sc) の任意問題で、AI コパイロットに「この事例を時系列で要約して」と頼むと、物語構造に整理された要約が返ってきます。自分の読み取りとの差分を必ず確認。

## まとめ

- 事例は物語として時系列で読む
- 4 構造（発覚 / 侵入 / 封じ込め / 復旧）を頭に置く
- 設問→構造→事例の順で時間配分
- AI 要約と自分の読み取りを差分学習

物語読解の訓練は再現性が高く、午後 II の長文事例にも応用できます。
`,
