    body: `# 過去問だけで合格できるIPA試験はどれ？

「過去問だけで合格できる」と言われる試験と、「過去問だけでは限界がある」試験があります。本記事では、各試験の特性を分析し、過去問演習の比重をどう設定すべきかを解説します。

> 本記事は 過去問AI が独自にまとめた学習ガイドです。試験要項の最新情報は必ず [IPA 公式ページ](https://www.ipa.go.jp/shiken/) で確認してください。

## 過去問依存度：高（過去問中心で合格可能）

### ITパスポート（IP）

[ITパスポート](/ip)は、過去問からの類似出題率が高く、過去3〜5年分を90%以上正答できる状態にすれば合格圏に入ります。

**理由**：
- CBT方式で同一の問題プールから出題される
- 知識問題が中心で「理解より暗記」が有効
- 選択肢の形式が固定化されており、過去問演習で対応力がつく

**推奨比率**：過去問演習 70% / 教科書・参考書 30%

### 情報セキュリティマネジメント（SG）

[情報セキュリティマネジメント](/sg)も過去問依存度が高い試験です。事例問題は長文ですが、問われる観点は固定化されています。

**推奨比率**：過去問演習 65% / 参考書 35%

## 過去問依存度：中（過去問＋概念理解が必要）

### 基本情報技術者（FE）

[基本情報技術者](/fe)の科目Aは過去問依存度が高いですが、科目B（アルゴリズム・疑似言語）は過去問だけでは対応できません。

**科目Aの対策**：過去問演習 70%
**科目Bの対策**：アルゴリズム理解 50% / 過去問演習 50%

科目Bは「疑似言語をトレースして動作を追う力」が求められ、過去問を解くだけでは身につきません。AIコパイロットに「このトレース手順を説明して」と依頼する使い方が効果的です。

### 応用情報技術者（AP）

[応用情報技術者](/ap)の午前は過去問依存度が高い（同一問題が再出題されることも多い）ですが、午後の記述問題は過去問だけでは不十分です。

**午前の対策**：過去問演習 75%
**午後の対策**：過去問演習 40% / 模範解答の構造分析 60%

## 過去問依存度：低（実力・論述力が必須）

### 高度試験（ST・SA・PM・SM・AU）：論文系

[ITストラテジスト](/st)・[システムアーキテクト](/sa)・[プロジェクトマネージャ](/pm)・[ITサービスマネージャ](/sm)・[システム監査技術者](/au)の午後IIは**論文試験**です。

過去問の「問題テーマ」に慣れることは重要ですが、実際の採点は「自分の経験に基づく論述」の質で決まります。過去問だけでは論述力は伸びません。

**必要な対策**：
- 過去問の問題テーマを把握（20%）
- 自分の担当プロジェクト・経験の棚卸し（40%）
- 論文草案をAIコパイロットに添削させる（40%）

### 高度試験（NW・DB・ES・SC）：技術系

[ネットワークスペシャリスト](/nw)・[データベーススペシャリスト](/db)・[エンベデッドシステムスペシャリスト](/es)・[情報処理安全確保支援士](/sc)の午後Iは、**技術の深い理解**が問われます。

過去問演習は有効ですが、「パターン暗記」だけでは対応できない応用問題が出ます。実務経験や参考書による知識補強が不可欠です。

**推奨比率**：過去問演習 50% / 技術書・実務演習 50%

## 過去問AI での効果的な活用法

- **過去問依存度が高い試験（IP・SG・FEの科目A・APの午前）**：[年度別モード](/quiz?mode=year)で直近3年分を徹底的に回す
- **過去問依存度が中程度の試験（FEの科目B・APの午後）**：間違えた問題にAIコパイロットで「解法の型」を教わる
- **過去問依存度が低い試験（高度試験の午後II）**：論文草案をAIコパイロットに「採点基準の観点でフィードバックして」と依頼

## まとめ

| 試験 | 過去問依存度 | 補強が必要な領域 |
|------|-------------|-----------------|
| IP | 高 | 最新用語のみ |
| SG | 高 | 法改正対応 |
| FE 科目A | 高 | — |
| FE 科目B | 中 | アルゴリズム理解 |
| AP 午前 | 高 | — |
| AP 午後 | 中 | 記述力 |
| 技術系高度（午後I） | 中 | 技術深掘り |
| 論文系高度（午後II） | 低 | 経験棚卸し・論述力 |

[試験区分を選んで演習を始める →](/)
`,
